package com.example.corejava.capstone;
import com.example.corejava.domain.*;
import java.util.concurrent.*;
public final class OrderProcessor implements AutoCloseable { private final InventoryManager inventory; private final BlockingQueue<Order> queue=new LinkedBlockingQueue<>(); private final ConcurrentHashMap<Long,Order> orders=new ConcurrentHashMap<>(); private final ExecutorService workers; public OrderProcessor(InventoryManager inventory,int workerCount){this.inventory=inventory;workers=Executors.newFixedThreadPool(workerCount);for(int i=0;i<workerCount;i++)workers.submit(this::consume);} public void submit(Order order){orders.put(order.id(),order);queue.add(order);} public Order get(Long id){return orders.get(id);} private void consume(){try{while(!Thread.currentThread().isInterrupted()){Order order=queue.take(); orders.put(order.id(),order.withStatus(OrderStatus.PROCESSING)); order.items().forEach(i->inventory.deduct(i.product(),i.quantity())); orders.put(order.id(),order.withStatus(OrderStatus.SHIPPED));}}catch(InterruptedException e){Thread.currentThread().interrupt();}} public void close(){workers.shutdownNow();}}
